def is_not_prime(n):
    """
    Return True if n is NOT a prime number, False if it is prime.
    This is typically used with filter() to identify non-prime numbers in a list.
    """
    if n < 2:
        return True
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return True
    return False

def differ_At_One_Bit_Pos(a, b):
    xor = a ^ b
    return xor != 0 and (xor & (xor - 1)) == 0

def remove_Occ(s, ch):
    s = list(s)
    first_index = None
    last_index = None
    for i, c in enumerate(s):
        if c == ch:
            if first_index is None:
                first_index = i
            last_index = i
    if first_index is None:
        return ''.join(s)
    if first_index == last_index:
        del s[first_index]
    else:
        # delete the later index first to keep indices valid
        del s[last_index]
        del s[first_index]
    return ''.join(s)

def check(num):
    reverse_num = int(str(num)[::-1])
    return num == 2 * reverse_num - 1

def is_octagonal(n):
    """
    Returns the n-th octagonal number.

    Octagonal numbers follow the formula: n * (3*n - 2)
    """
    return n * (3 * n - 2)

def count_Substrings(s):
    """
    Count the number of substrings of `s` (a string of digits) such that
    the sum of the digits in the substring equals the length of the substring.
    """
    n = len(s)
    # prefix[i] = sum of digits in s[0:i] minus i (to normalize comparison)
    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix[i] = prefix[i - 1] + int(s[i - 1]) - 1

    count_map = {}
    result = 0
    for i in range(n + 1):
        if prefix[i] in count_map:
            result += count_map[prefix[i]]
            count_map[prefix[i]] += 1
        else:
            count_map[prefix[i]] = 1

    return result

def recursive_list_sum(lst):
    """
    Recursively sum elements in a list.
    Handles nested lists by summing their elements as well.
    """
    total = 0
    for item in lst:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total
